function Pill({ children, tone = "violet" }: { children: React.ReactNode; tone?: "violet" | "mint" | "amber" | "rose" | "slate" }) {
  const tones = {
    violet: "bg-[#eeebff] text-[#5b4cc8]",
    mint: "bg-[#e4f8ef] text-[#167954]",
    amber: "bg-[#fff4d8] text-[#a66a00]",
    rose: "bg-[#ffe8ed] text-[#b43f5a]",
    slate: "bg-[#eef1f6] text-[#677188]",
  };
  return <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-bold uppercase tracking-[.08em] ${tones[tone]}`}>{children}</span>;
}

function Button({ children, onClick, variant = "primary", className = "", type = "button", disabled = false }: { children: React.ReactNode; onClick?: () => void; variant?: "primary" | "secondary" | "ghost" | "dark"; className?: string; type?: "button" | "submit"; disabled?: boolean }) {
  const styles = {
    primary: "bg-[#6c5ce7] text-white shadow-[0_10px_24px_rgba(108,92,231,.2)] hover:bg-[#5d4ed5]",
    secondary: "border border-[#dfe3ee] bg-white text-[#28344f] hover:border-[#c5cbe0] hover:bg-[#fafbff]",
    ghost: "text-[#657087] hover:bg-[#f0f2f8] hover:text-[#28344f]",
    dark: "bg-[#17223d] text-white shadow-[0_10px_24px_rgba(23,34,61,.2)] hover:bg-[#263452]",
  };
  return <button type={type} disabled={disabled} onClick={onClick} className={`inline-flex items-center justify-center gap-2 rounded-[12px] px-4 py-2.5 text-sm font-bold transition-all active:scale-[.98] disabled:cursor-not-allowed disabled:opacity-50 ${styles[variant]} ${className}`}>{children}</button>;
}

function Card({ children, className = "", onClick }: { children: React.ReactNode; className?: string; onClick?: () => void }) {
  return <div onClick={onClick} className={`rounded-[20px] border border-[#e9ebf2] bg-white shadow-[0_10px_36px_rgba(42,49,78,.045)] ${onClick ? "cursor-pointer transition-transform hover:-translate-y-0.5" : ""} ${className}`}>{children}</div>;
}

function SectionHeading({ eyebrow, title, action }: { eyebrow?: string; title: string; action?: React.ReactNode }) {
  return <div className="mb-5 flex items-end justify-between gap-4"><div>{eyebrow && <div className="mb-1 text-[10px] font-bold uppercase tracking-[.18em] text-[#7c8499]">{eyebrow}</div>}<h2 className="font-display text-[22px] font-bold tracking-[-.035em] text-[#17223d]">{title}</h2></div>{action}</div>;
}

function ScoreRing({ score, size = 148, label = "Readiness" }: { score: number; size?: number; label?: string }) {
  return <div className="relative grid shrink-0 place-items-center" style={{ width: size, height: size }}><div className="absolute inset-0 rounded-full" style={{ background: `conic-gradient(#6c5ce7 ${score * 3.6}deg, #ecebfa ${score * 3.6}deg)` }} /><div className="absolute inset-[8px] grid place-items-center rounded-full bg-white"><div className="text-center"><div className="font-display text-[35px] font-bold leading-none tracking-[-.07em] text-[#17223d]">{score}</div><div className="mt-1 text-[10px] font-bold uppercase tracking-[.14em] text-[#8991a4]">{label}</div></div></div></div>;
}

function Sparkline({ color = "#6c5ce7", points = "0,38 18,33 36,35 54,23 72,28 90,15 108,19 126,7" }: { color?: string; points?: string }) {
  return <svg viewBox="0 0 126 44" className="h-11 w-32 overflow-visible" aria-hidden="true"><polyline points={points} fill="none" stroke={color} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" /><circle cx="126" cy="7" r="3.2" fill={color} /></svg>;
}

function StatusDot({ tone = "mint" }: { tone?: "mint" | "amber" | "rose" }) { return <span className={`h-2 w-2 rounded-full ${tone === "mint" ? "bg-[#29ba7b]" : tone === "amber" ? "bg-[#e4a62f]" : "bg-[#ec6c82]"}`} />; }

