        <div className="relative min-h-[420px] lg:min-h-[520px]"><div className="absolute -right-24 top-3 h-[410px] w-[410px] rounded-full bg-[#eae7ff] blur-3xl lg:h-[510px] lg:w-[510px]" /><div className="absolute right-0 top-10 w-full max-w-[540px] rotate-[2deg] rounded-[28px] border border-[#e3e1f6] bg-white p-5 shadow-[0_30px_80px_rgba(61,56,128,.14)] sm:p-7"><div className="flex items-center justify-between"><div><div className="text-[10px] font-bold uppercase tracking-[.18em] text-[#9298a9]">Your career intelligence</div><div className="mt-1 font-display text-lg font-bold text-[#17223d]">Aarav’s profile</div></div><Pill tone="mint">Live estimate</Pill></div><div className="mt-6 grid grid-cols-[150px_1fr] items-center gap-5 border-b border-[#eef0f5] pb-6"><ScoreRing score={78} size={142} label="Readiness" /><div><div className="text-xs font-semibold text-[#8a91a3]">Target role</div><div className="mt-1 font-display text-base font-bold text-[#17223d]">AI / ML Engineer</div><div className="mt-4 flex items-center gap-2 text-xs font-semibold text-[#29a773]"><TrendingUp size={14} /> +12 points in 8 weeks</div></div></div><div className="mt-5 space-y-3"><div className="flex items-center justify-between text-xs font-bold text-[#56617a]"><span className="flex items-center gap-2"><span className="h-2.5 w-2.5 rounded-full bg-[#6c5ce7]" /> Your skills</span><span>91%</span></div><div className="h-2 rounded-full bg-[#f0effa]"><div className="h-2 w-[91%] rounded-full bg-[#6c5ce7]" /></div><div className="flex items-center justify-between text-xs font-bold text-[#56617a]"><span className="flex items-center gap-2"><span className="h-2.5 w-2.5 rounded-full bg-[#f3bd45]" /> Skill gaps</span><span>3 to close</span></div><div className="h-2 rounded-full bg-[#fff5df]"><div className="h-2 w-[43%] rounded-full bg-[#f3bd45]" /></div><div className="flex items-center justify-between text-xs font-bold text-[#56617a]"><span className="flex items-center gap-2"><span className="h-2.5 w-2.5 rounded-full bg-[#2aba7c]" /> Opportunity fit</span><span>42 matches</span></div><div className="h-2 rounded-full bg-[#e8f8f0]"><div className="h-2 w-[78%] rounded-full bg-[#2aba7c]" /></div></div></div><div className="absolute -bottom-4 -left-2 w-[245px] rounded-[20px] border border-[#e9e8f6] bg-white p-4 shadow-[0_20px_45px_rgba(61,56,128,.13)] sm:-left-8"><div className="flex items-center justify-between"><div className="text-[10px] font-bold uppercase tracking-[.14em] text-[#8d94a7]">Recommended next</div><Zap size={15} className="text-[#e4a62f]" /></div><div className="mt-2 font-display text-lg font-bold text-[#17223d]">Docker</div><div className="mt-1 text-xs leading-5 text-[#727c91]">Highest estimated opportunity gain</div><div className="mt-3 flex items-center justify-between text-[11px] font-bold"><span className="text-[#a46a00]">Priority 94</span><span className="text-[#29a773]">+16 matches</span></div></div></div>
