function AuthModal({ mode, setMode, onContinue, onClose }: { mode: AuthMode; setMode: (mode: AuthMode) => void; onContinue: () => void; onClose: () => void }) {
  return <div className="fixed inset-0 z-50 grid place-items-center bg-[#17223d]/45 p-5 backdrop-blur-sm"><div className="relative w-full max-w-[440px] rounded-[24px] bg-white p-7 shadow-[0_30px_100px_rgba(23,34,61,.25)]"><button onClick={onClose} className="absolute right-5 top-5 rounded-full p-2 text-[#8b93a5] hover:bg-[#f0f2f7]"><X size={17} /></button><Logo /><div className="mt-8 flex rounded-[10px] bg-[#f2f3f8] p-1"><button onClick={() => setMode("login")} className={`flex-1 rounded-lg py-2 text-sm font-bold ${mode === "login" ? "bg-white text-[#17223d] shadow-sm" : "text-[#8891a4]"}`}>Log in</button><button onClick={() => setMode("signup")} className={`flex-1 rounded-lg py-2 text-sm font-bold ${mode === "signup" ? "bg-white text-[#17223d] shadow-sm" : "text-[#8891a4]"}`}>Create account</button></div><h2 className="mt-7 font-display text-2xl font-bold tracking-[-.04em] text-[#17223d]">{mode === "login" ? "Welcome back." : "Start with your context."}</h2><p className="mt-2 text-sm leading-6 text-[#727c91]">{mode === "login" ? "Continue to your career intelligence workspace." : "A few details help us make every recommendation more relevant."}</p><div className="mt-6 grid gap-3"><label className="grid gap-1.5 text-xs font-bold text-[#59647b]">Email address<input className="h-11 rounded-[10px] border border-[#e1e5ee] bg-[#fbfbfd] px-3 text-sm outline-none focus:border-[#6c5ce7]" placeholder="you@example.com" type="email" /></label>{mode === "signup" && <label className="grid gap-1.5 text-xs font-bold text-[#59647b]">Full name<input className="h-11 rounded-[10px] border border-[#e1e5ee] bg-[#fbfbfd] px-3 text-sm outline-none focus:border-[#6c5ce7]" placeholder="Aarav Mehta" /></label>}<label className="grid gap-1.5 text-xs font-bold text-[#59647b]">Password<input className="h-11 rounded-[10px] border border-[#e1e5ee] bg-[#fbfbfd] px-3 text-sm outline-none focus:border-[#6c5ce7]" placeholder="At least 8 characters" type="password" /></label></div><Button onClick={onContinue} className="mt-6 w-full py-3">{mode === "login" ? "Continue to workspace" : "Create my profile"} <ArrowRight size={15} /></Button><div className="mt-4 text-center text-xs leading-5 text-[#9299aa]">By continuing, you agree to SkillBridge’s privacy-first approach. Your data stays scoped to your profile.</div></div></div>;
}

